/**
 * ✅ 심화한국사 (한국사검정 3/4급 대비) — 12강 콘텐츠 팩
 * 단원 자동 인식: ?unit=khadv_XX → 파일명 khadv_XX.html → 제목 숫자
 */
(function () {
  if (window.CUR_UNIT && window.CUR_UNIT.startsWith('khadv_')) {
    console.log('[korhistory_advanced_content.js] CUR_UNIT 이미 설정됨:', window.CUR_UNIT);
    return;
  }

  const qs = new URLSearchParams(location.search).get('unit');
  let unit = null;

  if (qs) {
    const m = qs.toLowerCase().match(/khadv[_-]?(\d{1,2})/);
    if (m) unit = `khadv_${m[1].padStart(2, '0')}`;
  }

  if (!unit) {
    const m2 = location.pathname.toLowerCase().match(/khadv[_-]?(\d{1,2})\.html/);
    if (m2) unit = `khadv_${m2[1].padStart(2, '0')}`;
  }

  if (!unit && document.title) {
    const m3 = document.title.match(/(\d{1,2})/);
    if (m3) unit = `khadv_${m3[1].padStart(2, '0')}`;
  }

  window.CUR_UNIT = unit || 'khadv_01';
})();

