    passage: [
      '삼국 시대에 우리나라에 처음 들어온 큰 사상이 바로 <b>불교</b>예요. 가장 먼저 받아들인 나라는 <b>고구려</b>로, <b>372년 소수림왕</b> 때 중국 전진의 승려 순도가 와서 전했답니다. 백제는 <b>384년 침류왕</b> 때 동진의 마라난타가 와서 불교를 전했어요. 가장 늦었던 신라는 귀족들의 반대가 심했지만, <b>527년 법흥왕</b> 때 <b>이차돈</b>의 순교를 계기로 불교를 정식으로 받아들였답니다. 삼국은 모두 불교를 통해 백성의 마음을 하나로 모으고 왕의 권위를 높였어요. 절을 짓고 큰 탑을 세우는 일은 곧 나라의 힘과 왕의 자랑을 보여 주는 일이기도 했답니다.',
      '신라가 삼국을 통일한 뒤 불교는 더욱 깊고 넓게 자라났어요. 통일신라를 대표하는 두 명승이 <b>원효</b>와 <b>의상</b>이에요. <b>원효</b>는 어려운 한문 경전을 모르는 평범한 백성들도 부처를 만날 수 있도록 노력했답니다. 마을을 돌아다니며 <b>"나무아미타불"</b>만 외워도 극락에 갈 수 있다고 가르쳤지요. 이렇게 백성 속으로 들어간 불교를 <b>대중불교</b>라고 해요. 반면 <b>의상</b>은 당나라에서 깊이 공부하고 돌아와 <b>화엄종</b>이라는 종파를 일으켰어요. 그는 \'모든 것이 하나로 통한다\'는 화엄 사상을 펴며 <b>부석사</b>를 비롯해 큰 절을 여러 곳에 세웠답니다. 두 사람은 같은 시대를 살면서도 서로 다른 길로 불교를 깊게 만들었어요.',
      '통일신라는 불교의 힘으로 눈부신 <b>불교 미술</b>을 꽃피웠어요. 가장 대표적인 곳이 경주의 <b>불국사</b>예요. 불국사 안에는 단정하고 안정감 있는 <b>석가탑</b>(3층 석탑)과 화려하게 장식된 <b>다보탑</b>이 마주 서 있답니다. 1966년 석가탑을 수리하다가 그 안에서 세계에서 가장 오래된 목판 인쇄물인 <b>무구정광대다라니경</b>이 발견되었어요. 신라 사람들이 이미 정교한 인쇄 기술을 가졌다는 자랑스러운 증거지요. 불국사 위쪽 토함산에는 화강암을 깎아 만든 인공 석굴 <b>석굴암</b>이 있어요. 석굴 안에는 자비로운 표정의 <b>본존불상</b>이 모셔져 있어 통일신라 조각 예술의 절정을 보여 준답니다.',
      '통일신라 사람들은 우리말로 노래도 즐겨 불렀어요. 이렇게 한자를 빌려 우리말로 적은 노래를 <b>향가</b>라고 해요. 죽은 누이를 그리워하며 지은 월명사의 <b>제망매가</b>, 화랑을 기리며 지은 충담사의 <b>찬기파랑가</b>, 처용이 부른 <b>처용가</b> 등이 유명하답니다. 한편 같은 시기 만주에서 일어난 <b>발해</b>도 불교 문화를 활짝 꽃피웠어요. 발해의 수도였던 상경 용천부 곳곳에는 큰 절터가 남아 있고, 정혜공주·정효공주 무덤에서는 정교한 벽화와 글이 발견되었답니다. 발해의 <b>석등</b>과 <b>영광탑</b>은 통일신라와 또 다른 발해만의 당당한 미를 보여 주지요. 통일신라와 발해가 함께 만들어 낸 \'남북국 시대\'의 문화는 우리 역사의 자랑스러운 한 페이지가 되었어요.'
    ],
